// Read both sitemaps (English Portugal site + Portuguese site) and keep the pages a prospect would ask about:
// products, pricing (the Portuguese pricing page has the full FAQ answers), solutions, industries,
// customer stories and platform news. Skips the blog, legal pages, the 2,000+ nursery directory pages, simulators and templates.
const keepEn = u => /\/en-pt(\/|$)/.test(u) && !/(\/legal|\/brand|\/lets-talk|\/press|\/careers)/i.test(u);
const keepPt = u => /\/pt(\/(seguros|wallet|cartao-refeicao|cheque-infancia|flexpay|budgets|transparencia-salarial|proposta-emprego|ai|descontos|precos|beneficios|parceiros|programa-de-recomendacoes|sobre-nos|colaborador|industrias?|solucao|historias|novidades-plataforma)(\/|$)|$)/.test(u);
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const xml = item.json.data || '';
  for (const m of xml.matchAll(/<loc>([^<]+)<\/loc>/g)) {
    const url = m[1].trim().replace(/\/\/+(?=[^\/])/g, (s, i) => i < 8 ? s : '/');
    if (seen.has(url)) continue;
    if (keepEn(url) || keepPt(url)) { seen.add(url); out.push({ json: { url } }); }
  }
}
return out;

// Turn each fetched page into clean text for the knowledge base.
// 1) Remove scripts, styles, menus and forms.
// 2) Remove boilerplate lines that appear on many pages (footer, menus, banners): left in, every chunk looks alike and retrieval gets worse.
const urls = $('Filter product & FAQ pages').all().map(i => i.json.url);
const pages = $input.all().map((item, i) => {
  let h = item.json.data || '';
  const t = h.match(/<title>([\s\S]*?)<\/title>/i);
  const title = t ? t[1].trim() : '';
  h = h.replace(/<(script|style|noscript|svg|nav|header|footer|form|button)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ');
  h = h.replace(/<(h[1-4])[^>]*>/gi, '\n\n## ');
  h = h.replace(/<\/(p|div|li|h[1-4]|section|span)>/gi, '\n');
  h = h.replace(/<[^>]+>/g, ' ');
  h = h.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/&euro;/g, '€');
  const lines = h.split('\n').map(l => l.replace(/[ \t]+/g, ' ').trim()).filter(l => l.length > 2);
  return { url: urls[i] || '', title, lines };
});
// Count on how many pages each line appears; drop lines found on more than 20% of pages
const freq = {};
pages.forEach(p => new Set(p.lines).forEach(l => { freq[l] = (freq[l] || 0) + 1; }));
const limit = Math.max(3, pages.length * 0.2);
return pages
  .map(p => ({ json: { url: p.url, title: p.title, text: p.lines.filter(l => freq[l] <= limit).join('\n') } }))
  .filter(p => p.json.text.length > 300);

// Two sitemaps: English (Portugal) and Portuguese. Add /es or /it sitemaps here to cover more markets.
return [
  { json: { sitemap: 'https://www.coverflex.com/en-pt/pages-sitemap.xml' } },
  { json: { sitemap: 'https://www.coverflex.com/pt/pages-sitemap.xml' } },
];
